fields.InputDefinition:
{
  "goal": "Open the application switcher dropdown next to the logo (NOT the Ctrl+K search box) and switch to the 'Actions' application. It lands on the 'Actions Overview' page (default nav item). Pages can take 10-30s to load in this resource-constrained environment — wait, don't navigate away. Verify the overview renders its KPI metric cards (Total Actions with an Active/Pending/Disabled breakdown, Total Executions, Categories, AI Generated). Then click the 'Total Actions' metric card and confirm the app navigates to another Actions view (e.g. the Explorer/list of actions). Seeing the metric cards render and the card click drive navigation is success.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}
